int enemy_overlay(int id, int column) {
    if (id < 0 || id >= enemy_ids() || column < 0 || column >= kEnemyColumns)
        return -1;
    return kOverlays[id][column];
}

const char* enemy_name(int id) {
    if (id < 0 || id >= static_cast<int>(sizeof(kNames) / sizeof(kNames[0])))
        return nullptr;
    return kNames[id];
}

int enemy_ids() {
    return static_cast<int>(sizeof(kNames) / sizeof(kNames[0]));
}

